/* ============================================================
   portrait-data.js
   The sketch (assets/images/sketch.jpeg) stored as text (a "data URL").
   Why: when index.html is opened straight from the disk (file://),
   Chrome won't let a script read the pixels of a normal image file,
   so the 0s-and-1s portrait would be skipped. An image stored as a
   data URL can always be read, so the portrait works either way.
   Grayscale and half size (533x640) are enough: the script only looks at
   brightness, and the portrait is drawn about 500px tall.
   To change the portrait: replace sketch.jpeg and re-generate this file.
   ============================================================ */
const PORTRAIT_SRC = 'data:image/jpeg;base64,';
